'use strict';

// This suite only runs against the fingerprint-verified synthetic server created
// by scripts/test-functional.js. Credentials are generated by that runner.
const { test } = require('node:test');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const { spawn } = require('node:child_process');
const path = require('node:path');
const {
  verifyTestApiServer, getTestDatabase, loginTestAdmin, getTestAdminCredentials
} = require('./test-support');

const ROOT = path.resolve(__dirname, '../..');
const syntheticPassword = () => 'Synthetic-' + crypto.randomBytes(20).toString('hex');
const hashToken = token => crypto.createHash('sha256').update(token).digest('hex');
const rawToken = session => session.cookie.slice('rally_session='.length);

async function http(baseUrl, route, { method = 'GET', session, body, headers = {} } = {}) {
  const requestHeaders = { ...headers };
  if (session) {
    requestHeaders.Cookie = session.cookie;
    if (!['GET', 'HEAD', 'OPTIONS'].includes(method)) requestHeaders['X-CSRF-Token'] = session.csrfToken;
  }
  Object.assign(requestHeaders, headers);
  if (body !== undefined) requestHeaders['Content-Type'] ||= 'application/json';
  const response = await fetch(baseUrl + route, {
    method, headers: requestHeaders, body: body === undefined ? undefined : JSON.stringify(body),
    redirect: 'error', signal: AbortSignal.timeout(10000)
  });
  const text = await response.text();
  let data;
  try { data = JSON.parse(text); } catch { data = null; }
  return { status: response.status, data, headers: response.headers };
}

async function login(baseUrl, email, password, headers = {}) {
  const result = await http(baseUrl, '/auth/login', { method: 'POST', body: { email, password }, headers });
  if (result.status === 200) result.session = {
    cookie: (result.headers.get('set-cookie') || '').split(';')[0],
    csrfToken: result.data.data.csrfToken,
    user: result.data.data.user
  };
  return result;
}

function status(result, expected) {
  assert.equal(result.status, expected, 'HTTP status must reflect authentication and authorization');
}

function assertPublicUser(user) {
  assert(user && typeof user.id === 'number');
  assert.equal(user.senha_hash, undefined);
  assert.equal(user.password, undefined);
  assert.equal(user.session_hash, undefined);
  assert.equal(user.sessionHash, undefined);
}

test('login, sessions and server-side permissions', { concurrency: false }, async t => {
  const baseUrl = await verifyTestApiServer();
  const db = getTestDatabase();
  await db.connect();
  const credentials = getTestAdminCredentials();
  const admin = await loginTestAdmin(baseUrl);
  const accounts = new Map();
  const accountPassword = syntheticPassword();
  try {
    await t.test('all business route methods reject anonymous requests', async () => {
      for (const [route, method] of [
        ['/pontuacoes/1', 'GET'], ['/pontuacoes/1', 'POST'], ['/rallies', 'GET'], ['/rallies', 'POST'], ['/rallies/1', 'PUT'],
        ['/rallies/1/start', 'PATCH'], ['/rallies/1', 'DELETE'], ['/tribos', 'GET'],
        ['/tribos', 'POST'], ['/tribos/1', 'PUT'], ['/tribos/1', 'DELETE'],
        ['/tribos/1/membros', 'GET'], ['/tribos/ranking/1', 'GET'], ['/tribos/catalogo', 'GET'], ['/admin/users', 'GET']
      ]) status(await http(baseUrl, route, { method }), 401);
      status(await http(baseUrl, '/auth/session'), 401);
    });

    await t.test('unknown users and wrong passwords receive the same generic refusal', async () => {
      const unknown = await login(baseUrl, 'missing-' + crypto.randomUUID() + '@example.invalid', syntheticPassword());
      const wrong = await login(baseUrl, credentials.email, syntheticPassword());
      status(unknown, 401);
      status(wrong, 401);
      assert.deepEqual(unknown.data, wrong.data);
      assert.equal(unknown.headers.get('set-cookie'), null);
      assert.equal(wrong.headers.get('set-cookie'), null);
    });

    await t.test('login issues a protected opaque cookie and session restores user and CSRF', async () => {
      const suppliedToken = crypto.randomBytes(32).toString('hex');
      const logged = await login(baseUrl, credentials.email, credentials.password, { Cookie: 'rally_session=' + suppliedToken });
      status(logged, 200);
      const cookie = logged.headers.get('set-cookie');
      assert.match(cookie, /(?:^|;)\s*HttpOnly(?:;|$)/i);
      assert.match(cookie, /(?:^|;)\s*SameSite=Strict(?:;|$)/i);
      assert.match(cookie, /(?:^|;)\s*Path=\/(?:;|$)/i);
      assert.match(cookie, /(?:^|;)\s*Max-Age=\d+/i);
      assert.match(rawToken(logged.session), /^[a-f0-9]{64}$/);
      assert.notEqual(rawToken(logged.session), suppliedToken, 'pre-login cookie must not fix the authenticated session');
      const restored = await http(baseUrl, '/auth/session', { session: logged.session });
      status(restored, 200);
      assert.equal(restored.data.data.user.id, logged.session.user.id);
      assert.equal(restored.data.data.csrfToken, logged.session.csrfToken);
      assertPublicUser(restored.data.data.user);
      assert.match(restored.headers.get('cache-control') || '', /no-store/i);
      const stored = await db.get('SELECT session_hash FROM auth_sessions WHERE session_hash = ?', [hashToken(rawToken(logged.session))]);
      assert.equal(stored.session_hash, hashToken(rawToken(logged.session)));
      assert.notEqual(stored.session_hash, rawToken(logged.session));
      status(await http(baseUrl, '/auth/logout', { method: 'POST', session: logged.session }), 200);
    });

    await t.test('a new login rotates and revokes a valid previous session cookie', async () => {
      const previous = await login(baseUrl, credentials.email, credentials.password);
      status(previous, 200);
      const rotated = await login(baseUrl, credentials.email, credentials.password, { Cookie: previous.session.cookie });
      status(rotated, 200);
      assert.notEqual(rotated.session.cookie, previous.session.cookie);
      status(await http(baseUrl, '/auth/session', { session: previous.session }), 401);
      status(await http(baseUrl, '/auth/session', { session: rotated.session }), 200);
      status(await http(baseUrl, '/auth/logout', { method: 'POST', session: rotated.session }), 200);
    });

    await t.test('malformed credential JSON returns a generic error without echoing its body', async () => {
      const secret = syntheticPassword();
      const response = await fetch(baseUrl + '/auth/login', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: '{"password":"' + secret + '",}', signal: AbortSignal.timeout(10000)
      });
      assert.equal(response.status, 400);
      const body = await response.text();
      assert.equal(body.includes(secret), false, 'malformed JSON must not echo credential fragments');
    });

    await t.test('mutations require the session CSRF token, including logout', async () => {
      const payload = { nome: 'Rally sintetico de autorizacao', data_inicio: '2026-11-01', data_fim: '2026-12-31', tribos_ids: [1, 2] };
      status(await http(baseUrl, '/rallies', { method: 'POST', headers: { Cookie: admin.cookie }, body: payload }), 403);
      status(await http(baseUrl, '/rallies', { method: 'POST', session: admin, headers: { 'X-CSRF-Token': 'invalid' }, body: payload }), 403);
      status(await http(baseUrl, '/auth/logout', { method: 'POST', headers: { Cookie: admin.cookie } }), 403);
      status(await http(baseUrl, '/rallies', { method: 'POST', session: admin, body: payload }), 201);
      status(await http(baseUrl, '/auth/session', { session: admin }), 200);
    });

    await t.test('administrators create pending accounts with salted password hashes', async () => {
      for (const role of ['lider', 'auxiliar', 'participante']) {
        const email = 'fixture-' + role + '-' + crypto.randomUUID() + '@example.invalid';
        const created = await http(baseUrl, '/admin/users', { method: 'POST', session: admin,
          body: { nome_completo: 'Fixture ' + role, email, password: accountPassword, tipo_usuario: role } });
        status(created, 201);
        assert.equal(created.data.data.aprovacao, 'pendente');
        assertPublicUser(created.data.data);
        accounts.set(role, { user: created.data.data, email });
        status(await login(baseUrl, email, accountPassword), 401);
      }
      const rows = await db.all('SELECT senha_hash FROM usuarios WHERE tipo_usuario != ?', ['admin']);
      assert.equal(rows.length, 3);
      for (const row of rows) {
        assert.notEqual(row.senha_hash, accountPassword);
        assert.match(row.senha_hash, /^scrypt[$:]/);
      }
      assert.equal(new Set(rows.map(row => row.senha_hash)).size, rows.length, 'same password must receive distinct random salts');
      const list = await http(baseUrl, '/admin/users', { session: admin });
      status(list, 200);
      assert(Array.isArray(list.data.data));
      for (const user of list.data.data) assertPublicUser(user);
      const invalid = await http(baseUrl, '/admin/users', { method: 'POST', session: admin, body: {
        nome_completo: 'Escalacao nao autorizada', email: 'invalid-role@example.invalid', password: accountPassword, tipo_usuario: 'admin'
      } });
      assert([400, 403].includes(invalid.status));
    });

    await t.test('approved non-administrators authenticate but cannot use administrative or business routes', async () => {
      for (const [role, account] of accounts) {
        status(await http(baseUrl, '/admin/users/' + account.user.id + '/approval', { method: 'PATCH', session: admin,
          body: { aprovacao: 'aprovado', motivo: 'Aprovacao de fixture sintetica' } }), 200);
        const logged = await login(baseUrl, account.email, accountPassword);
        status(logged, 200);
        account.session = logged.session;
        assert.equal(logged.session.user.tipo_usuario, role);
        status(await http(baseUrl, '/auth/session', { session: logged.session }), 200);
        for (const [route, method] of [
          ['/pontuacoes/1', 'GET'], ['/pontuacoes/1', 'POST'], ['/rallies', 'GET'], ['/rallies', 'POST'], ['/rallies/1/start', 'PATCH'], ['/rallies/1', 'DELETE'],
          ['/tribos', 'GET'], ['/tribos/1/membros', 'GET'], ['/tribos/ranking/1', 'GET'], ['/tribos/catalogo', 'GET'], ['/admin/users', 'GET'],
          ['/admin/users/' + account.user.id + '/approval', 'PATCH']
        ]) status(await http(baseUrl, route, { method, session: logged.session, body: method === 'GET' ? undefined : {} }), 403);
      }
    });

    await t.test('disabling an account invalidates its current session and blocks new logins', async () => {
      const account = accounts.get('auxiliar');
      status(await http(baseUrl, '/admin/users/' + account.user.id + '/status', { method: 'PATCH', session: admin,
        body: { status: 'inativo', motivo: 'Desativacao sintetica de teste' } }), 200);
      status(await http(baseUrl, '/auth/session', { session: account.session }), 401);
      status(await login(baseUrl, account.email, accountPassword), 401);
      status(await http(baseUrl, '/admin/users/' + account.user.id + '/status', { method: 'PATCH', session: admin,
        body: { status: 'ativo', motivo: 'Reativacao sintetica de teste' } }), 200);
      status(await http(baseUrl, '/auth/session', { session: account.session }), 401);
    });

    await t.test('approval and role are rechecked for an already-issued session', async () => {
      const participant = accounts.get('participante');
      await db.run('UPDATE usuarios SET aprovacao = ? WHERE id = ?', ['pendente', participant.user.id]);
      status(await http(baseUrl, '/auth/session', { session: participant.session }), 401);
      await db.run('UPDATE usuarios SET aprovacao = ? WHERE id = ?', ['aprovado', participant.user.id]);
      const logged = await login(baseUrl, participant.email, accountPassword);
      status(logged, 200);
      // Change only this synthetic account, never the bootstrapped admin.
      await db.run('UPDATE usuarios SET tipo_usuario = ? WHERE id = ?', ['admin', participant.user.id]);
      status(await http(baseUrl, '/rallies', { session: logged.session }), 200);
      await db.run('UPDATE usuarios SET tipo_usuario = ? WHERE id = ?', ['participante', participant.user.id]);
      status(await http(baseUrl, '/rallies', { session: logged.session }), 403);
    });

    await t.test('absolute and idle expiry each independently invalidate sessions', async () => {
      const absolute = await login(baseUrl, credentials.email, credentials.password);
      status(absolute, 200);
      await db.run('UPDATE auth_sessions SET created_at = ?, last_seen_at = ?, expires_at = ? WHERE session_hash = ?',
        [Date.now() - 9 * 60 * 60 * 1000, Date.now() - 2000, Date.now() - 1000, hashToken(rawToken(absolute.session))]);
      status(await http(baseUrl, '/auth/session', { session: absolute.session }), 401);
      const idle = await login(baseUrl, credentials.email, credentials.password);
      status(idle, 200);
      await db.run('UPDATE auth_sessions SET created_at = ?, last_seen_at = ? WHERE session_hash = ?',
        [Date.now() - 60 * 60 * 1000, Date.now() - 31 * 60 * 1000, hashToken(rawToken(idle.session))]);
      status(await http(baseUrl, '/auth/session', { session: idle.session }), 401);
    });

    await t.test('logout revokes only its session and clears the browser cookie', async () => {
      const logged = await login(baseUrl, credentials.email, credentials.password);
      status(logged, 200);
      const ended = await http(baseUrl, '/auth/logout', { method: 'POST', session: logged.session });
      status(ended, 200);
      assert.match(ended.headers.get('set-cookie') || '', /(?:Max-Age=0|Expires=Thu, 01 Jan 1970)/i);
      status(await http(baseUrl, '/auth/session', { session: logged.session }), 401);
      status(await http(baseUrl, '/auth/session', { session: admin }), 200);
    });

    await t.test('auditing preserves events and excludes password and raw session credentials', async () => {
      const audit = await db.all('SELECT * FROM auth_audit ORDER BY id');
      assert(audit.length > 5, 'authentication and account changes must produce audit events');
      assert(audit.some(row => row.event === 'bootstrap_admin'));
      const text = JSON.stringify(audit);
      for (const secret of [credentials.password, accountPassword, rawToken(admin)]) assert.equal(text.includes(secret), false);
      const event = audit[0];
      await assert.rejects(db.run('UPDATE auth_audit SET detail = ? WHERE id = ?', ['tampered', event.id]));
      await assert.rejects(db.run('DELETE FROM auth_audit WHERE id = ?', [event.id]));
      assert.deepEqual(await db.get('SELECT * FROM auth_audit WHERE id = ?', [event.id]), event);
    });

    await t.test('bootstrap cannot create another administrator or leak credentials after first use', async () => {
      const secret = crypto.randomBytes(32).toString('hex');
      const password = syntheticPassword();
      const output = await new Promise((resolve, reject) => {
        const child = spawn(process.execPath, ['scripts/bootstrap-admin.js', '--json'], {
          cwd: ROOT, env: { ...process.env, RALLY_BOOTSTRAP_SECRET: secret }, stdio: ['pipe', 'pipe', 'pipe']
        });
        let text = '';
        child.stdout.on('data', chunk => { text += chunk; });
        child.stderr.on('data', chunk => { text += chunk; });
        child.once('error', reject);
        child.once('close', code => resolve({ code, text }));
        child.stdin.end(JSON.stringify({ secret, nome_completo: 'Segundo administrador proibido',
          email: 'second-' + crypto.randomUUID() + '@example.invalid', password }));
      });
      assert.notEqual(output.code, 0);
      assert.equal(output.text.includes(secret), false);
      assert.equal(output.text.includes(password), false);
      const count = await db.get("SELECT COUNT(*) AS total FROM usuarios WHERE tipo_usuario = 'admin'");
      assert.equal(count.total, 1);
      const sentinel = await db.all('SELECT * FROM auth_bootstrap');
      assert.equal(sentinel.length, 1);
    });

    await t.test('repeated failed authentication is rate limited with a bounded retry delay', async () => {
      const email = 'rate-limit-' + crypto.randomUUID() + '@example.invalid';
      let blocked;
      for (let attempt = 0; attempt < 30; attempt++) {
        const result = await login(baseUrl, email, syntheticPassword());
        if (result.status === 429) { blocked = result; break; }
        status(result, 401);
      }
      assert(blocked, 'login attempts must eventually be throttled');
      const retry = Number(blocked.headers.get('retry-after'));
      assert(Number.isFinite(retry) && retry > 0 && retry <= 3600);
    });
  } finally {
    await http(baseUrl, '/auth/logout', { method: 'POST', session: admin });
    await db.close();
  }
});
